package com.huimeng.bookshop.core;
import android.test.AndroidTestCase;import com.huimeng.bookshop.core.local.*;import org.json.*;
@SuppressWarnings("deprecation")
public class LocalConflictTest extends AndroidTestCase {
 private LocalDatabase db;private String file,space;
 @Override protected void setUp()throws Exception{super.setUp();file="conflict-"+java.util.UUID.randomUUID()+".db";db=new LocalDatabase(getContext(),file);space=new LocalSpaceStore(db).ensureActiveSpace();}
 @Override protected void tearDown()throws Exception{db.close();getContext().deleteDatabase(file);super.tearDown();}
 public void testResolutionCreatesNewIdAndCurrentBaseline()throws Exception{db.saveConfirmed(space,"addresses","a",new JSONObject().put("id","a").put("detail","old"),1);String op=db.mutate(space,"addresses","a","address.save",new JSONObject().put("id","a").put("detail","local"),false);db.saveConfirmed(space,"addresses","a",new JSONObject().put("id","a").put("detail","server"),2);db.getWritableDatabase().execSQL("UPDATE sync_operations SET state='CONFLICT' WHERE operation_id=?",new Object[]{op});String next=new LocalConflictResolver(db).retryWithLocal(space,op);assertFalse(next.equals(op));assertEquals(1,db.pending(space).length());assertEquals(2,db.pending(space).getJSONObject(0).getLong("baseVersion"));assertEquals("local",db.entity(space,"addresses","a").getString("detail"));}
 public void testDiscardKeepsArchiveAndRestoresConfirmed()throws Exception{db.saveConfirmed(space,"addresses","a",new JSONObject().put("id","a").put("detail","server"),2);String op=db.mutate(space,"addresses","a","address.save",new JSONObject().put("id","a").put("detail","local"),false);new LocalConflictResolver(db).keepServer(space,op);assertEquals(0,db.pending(space).length());assertEquals("server",db.entity(space,"addresses","a").getString("detail"));assertFalse(db.metadata("discarded:"+op).isEmpty());}
 public void testResolutionRetainsNewestPendingEdit()throws Exception{db.saveConfirmed(space,"addresses","a",new JSONObject().put("id","a").put("detail","old"),1);String op=db.mutate(space,"addresses","a","address.save",new JSONObject().put("detail","first"),false);db.mutate(space,"addresses","a","address.save",new JSONObject().put("detail","latest"),false);db.saveConfirmed(space,"addresses","a",new JSONObject().put("id","a").put("detail","server"),2);db.getWritableDatabase().execSQL("UPDATE sync_operations SET state='CONFLICT' WHERE operation_id=?",new Object[]{op});new LocalConflictResolver(db).retryWithLocal(space,op);assertEquals(1,db.pending(space).length());assertEquals("latest",db.pending(space).getJSONObject(0).getJSONObject("payload").getString("detail"));}
}
